import{c as r,Q as t,j as i,m as a}from"./chunks/framework.BPmZ9ESu.js";const o="/cours/assets/exercice4.CAbFpGOz.png",n="/cours/assets/exercice4-1.B6aO5FJb.png",s="/cours/assets/export-pdf.nrscGDyZ.gif",g=JSON.parse('{"title":"Citations, révision et remise","description":"Finaliser un document Word avant la remise","frontmatter":{"title":"Citations, révision et remise","description":"Finaliser un document Word avant la remise"},"headers":[],"relativePath":"modules/03-word/04-finalisation.md","filePath":"modules/03-word/04-finalisation.md"}'),d={name:"modules/03-word/04-finalisation.md"};function u(c,e,l,p,m,f){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="citations-revision-et-remise" tabindex="-1">Citations, révision et remise <a class="header-anchor" href="#citations-revision-et-remise" aria-label="Permalink to &quot;Citations, révision et remise&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p>Terminez le même document en lui ajoutant les éléments de finition qui le rapprochent d&#39;un vrai travail remis.</p><p>À faire dans cette étape :</p><ul><li>insérer au moins une citation en format APA liée à une information de votre document (voir le carré violet sur l&#39;image);</li><li>ajouter une note de bas de page explicative à un endroit pertinent (voir les carrés jaunes sur l&#39;image);</li><li>générer une bibliographie;</li><li>mettre à jour la table des matières si elle est déjà insérée;</li><li>enregistrer une version <code>dotx</code> pour facilement réutiliser le modèle;</li><li>enregistrer ensuite une version PDF pour vérifier le résultat final;</li></ul><figure><img src="'+o+'" alt="Exemple d&#39;une citation APA et d&#39;une bibliographie dans Word" class="img-bordered w-full h-auto object-contain"><figcaption>Exemples d&#39;une citation (en violet) et d&#39;une note de bas de page (en jaune)</figcaption></figure><figure><img src="'+n+'" alt="Exemple d&#39;une note de bas de page dans Word" class="img-bordered w-full h-auto object-contain"><figcaption>Exemple d&#39;une bibliographie automatiquement générée à partir des citations insérées dans le texte</figcaption></figure><h2 id="ressources-pour-vous-aider" tabindex="-1">Ressources pour vous aider <a class="header-anchor" href="#ressources-pour-vous-aider" aria-label="Permalink to &quot;Ressources pour vous aider&quot;">​</a></h2><h3 id="inserer-des-notes-de-bas-de-page-et-des-notes-de-fin" tabindex="-1">Insérer des notes de bas de page et des notes de fin <a class="header-anchor" href="#inserer-des-notes-de-bas-de-page-et-des-notes-de-fin" aria-label="Permalink to &quot;Insérer des notes de bas de page et des notes de fin&quot;">​</a></h3><p>Explique comment ajouter une note explicative dans Word. C&#39;est utile pour distinguer clairement une précision de bas de page d&#39;une véritable citation de source.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-des-notes-de-bas-de-page-et-des-notes-de-fin-61f3fb1a-4717-414c-9a8f-015a5f3ff4cb" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="creer-une-bibliographie-des-citations-et-des-references" tabindex="-1">Créer une bibliographie, des citations et des références <a class="header-anchor" href="#creer-une-bibliographie-des-citations-et-des-references" aria-label="Permalink to &quot;Créer une bibliographie, des citations et des références&quot;">​</a></h3><p>Montre comment gérer les sources directement dans Word. C&#39;est important pour produire des citations cohérentes et une bibliographie finale en style APA.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/cr%C3%A9er-une-bibliographie-des-citations-et-des-r%C3%A9f%C3%A9rences-17686589-4824-4940-9c69-342c289fa2a5" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="inserer-une-table-des-matieres" tabindex="-1">Insérer une table des matières <a class="header-anchor" href="#inserer-une-table-des-matieres" aria-label="Permalink to &quot;Insérer une table des matières&quot;">​</a></h3><p>Permet de générer la table des matières automatiquement. C&#39;est utile à la fin pour vérifier que la structure du document fonctionne toujours correctement.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-une-table-des-mati%C3%A8res-882e8564-0edb-435e-84b5-1d8552ccf0c0" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="creer-un-modele" tabindex="-1">Créer un modèle <a class="header-anchor" href="#creer-un-modele" aria-label="Permalink to &quot;Créer un modèle&quot;">​</a></h3><p>Explique comment enregistrer un document comme gabarit réutilisable. C&#39;est nécessaire pour remettre correctement la partie A en format DOTX. De plus, une fois votre modèle enregistré au bon endroit, il apparaît dans les modèles proposés lorsqu&#39;on vous démarrez un nouveau projet (je vous le montrerai en classe).</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/cr%C3%A9er-un-mod%C3%A8le-86a1d089-5ae2-4d53-9042-1191bce57deb" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="enregistrer-ou-convertir-au-format-pdf-ou-xps" tabindex="-1">Enregistrer ou convertir au format PDF ou XPS <a class="header-anchor" href="#enregistrer-ou-convertir-au-format-pdf-ou-xps" aria-label="Permalink to &quot;Enregistrer ou convertir au format PDF ou XPS&quot;">​</a></h3><p>Montre comment produire une version PDF stable du document. C&#39;est utile pour remettre une copie finale dont la mise en page ne bougera plus. Allez vraiment dans <strong>Exporter --&gt; Créer un document PDF/XPS</strong>. Évitez le Create/Save Adobe PDF, car ça prend un abonnement payant.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/enregistrer-ou-convertir-au-format-pdf-ou-xps-dans-les-applications-de-bureau-office-d85416c5-7d77-4fd6-a216-6f4bf7c7c110" target="_blank" rel="noreferrer">Microsoft Support</a></p><figure><img src="'+s+'" alt="Démonstration de l&#39;exportation d&#39;un document Word en PDF" class="img-bordered"><figcaption>Chemin recommandé pour exporter en PDF dans Word</figcaption></figure>',24)])])}const h=r(d,[["render",u]]);export{g as __pageData,h as default};
